import "fmt"

func Memoize[K comparable, V any](f func(K) V) func(K) V {
	cache := make(map[K]V)
	return func(k K) V {
		if v, ok := cache[k]; ok {
			return v
		}
		v := f(k)
		cache[k] = v
		return v
	}
}

func main() {
	calls := 0
	square := Memoize(func(n int) int {
		calls++
		return n * n
	})
	fmt.Println(square(12), square(12), square(5))
	fmt.Println("haqiqiy hisoblashlar:", calls)
}

