func MapErr[T, U any](s []T, f func(T) (U, error)) ([]U, error) {
	out := make([]U, 0, len(s))
	for i, v := range s {
		u, err := f(v)
		if err != nil {
			return nil, fmt.Errorf("element %d: %w", i, err)
		}
		out = append(out, u)
	}
	return out, nil
}

func main() {
	nums, err := MapErr([]string{"10", "20", "30"}, strconv.Atoi)
	fmt.Println(nums, err)
	nums, err = MapErr([]string{"10", "abc", "30"}, strconv.Atoi)
	fmt.Println(nums, err)
}

