func Chunk[T any](s []T, size int) [][]T {
	var out [][]T
	for size < len(s) {
		s, out = s[size:], append(out, s[:size])
	}
	return append(out, s)
}

func main() {
	ids := []int{1, 2, 3, 4, 5, 6, 7}
	fmt.Println(Chunk(ids, 3))
	fmt.Println(Chunk([]string{"a", "b", "c", "d"}, 2))
