import "fmt"

func Unique[T comparable](s []T) []T {
	seen := make(map[T]struct{}, len(s))
	var out []T
	for _, v := range s {
		if _, ok := seen[v]; !ok {
			seen[v] = struct{}{}
			out = append(out, v)
		}
	}
	return out
}

func main() {
	fmt.Println(Unique([]int{3, 1, 3, 2, 1, 2}))
	fmt.Println(Unique([]string{"a", "b", "a", "c", "b"}))
}

