type Student struct {
	Name  string
	Group string
}

func GroupBy[T any, K comparable](s []T, key func(T) K) map[K][]T {
	groups := make(map[K][]T)
	for _, v := range s {
		k := key(v)
		groups[k] = append(groups[k], v)
	}
	return groups
}

func main() {
	students := []Student{
		{"Aziz", "A-1"}, {"Dilnoza", "B-2"}, {"Bobur", "A-1"}, {"Malika", "B-2"}, {"Sardor", "C-3"},
	}
	groups := GroupBy(students, func(s Student) string { return s.Group })
	names := make([]string, 0, len(groups))
	for g := range groups {
		names = append(names, g)
	}
	slices.Sort(names)
	for _, g := range names {
		fmt.Println(g, groups[g])
	}
}

