type Student struct {
	Name  string
	Score int
}

func MaxBy[T any, K cmp.Ordered](s []T, key func(T) K) (T, bool) {
	var best T
	if len(s) == 0 {
		return best, false
	}
	best = s[0]
	for _, v := range s[1:] {
		if key(v) > key(best) {
			best = v
		}
	}
	return best, true
}

func main() {
	students := []Student{{"Aziz", 78}, {"Dilnoza", 94}, {"Bobur", 85}}
	top, _ := MaxBy(students, func(s Student) int { return s.Score })
	fmt.Println(top.Name, top.Score)
	longest, _ := MaxBy([]string{"go", "generics", "tip"}, func(s string) int { return len(s) })
	fmt.Println(longest)
}

