import "fmt"

type Student struct {
	Name  string
	Score float64
}

func Filter[T any](s []T, keep func(T) bool) []T {
	var out []T
	for _, v := range s {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, 0, len(s))
	for _, v := range s {
		out = append(out, f(v))
	}
	return out
}

func Reduce[T, A any](s []T, init A, f func(A, T) A) A {
	acc := init
	for _, v := range s {
		acc = f(acc, v)
	}
	return acc
}

func main() {
	students := []Student{{"Aziz", 78}, {"Dilnoza", 94.5}, {"Bobur", 52}, {"Malika", 88}}
	passed := Filter(students, func(s Student) bool { return s.Score >= 60 })
	scores := Map(passed, func(s Student) float64 { return s.Score })
	sum := Reduce(scores, 0.0, func(acc, v float64) float64 { return acc + v })
	fmt.Println(len(passed), "ta talaba o'tdi")
	fmt.Printf("o'rtacha: %.2f\n", sum/float64(len(scores)))
}

