func BinarySearch[T cmp.Ordered](sorted []T, target T) int {
	lo, hi := 0, len(sorted)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case sorted[mid] == target:
			return mid
		case sorted[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

func main() {
	nums := []int{2, 5, 8, 12, 16, 23, 38}
	fmt.Println(BinarySearch(nums, 23), BinarySearch(nums, 7))
	names := []string{"Aziz", "Bobur", "Dilnoza", "Malika"}
	fmt.Println(BinarySearch(names, "Dilnoza"))
