func (l *List[T]) Push(v T) { l.head = &node[T]{val: v, next: l.head} }

func (l *List[T]) ToSlice() []T {
	var out []T
	for n := l.head; n != nil; n = n.next {
		out = append(out, n.val)
	}
	return out
}

func (l *List[T]) Reverse() {
	var prev *node[T]
	for cur := l.head; cur != nil; {
		next := cur.next
		cur.next = prev
		prev, cur = cur, next
	}
	l.head = prev
}

func main() {
	var l List[int]
	for i := 1; i <= 5; i++ {
		l.Push(i * 10)
	}
	fmt.Println(l.ToSlice())
	l.Reverse()
	fmt.Println(l.ToSlice())
