func (n *node[T]) insert(v T) *node[T] {
	if n == nil {
		return &node[T]{val: v}
	}
	if v < n.val {
		n.left = n.left.insert(v)
	} else {
		n.right = n.right.insert(v)
	}
	return n
}

func (n *node[T]) contains(v T) bool {
	if n == nil {
		return false
	}
	switch c := cmp.Compare(v, n.val); {
	case c < 0:
		return n.left.contains(v)
	case c > 0:
		return n.right.contains(v)
	}
	return true
}

func (n *node[T]) height() int {
	if n == nil {
		return 0
	}
	return 1 + max(n.left.height(), n.right.height())
}

func main() {
	var root *node[int]
	for _, v := range []int{8, 3, 10, 1, 6, 14, 4} {
		root = root.insert(v)
	}
	fmt.Println(root.contains(6), root.contains(7))
	fmt.Println(root.height(), (*node[int])(nil).height())
}

