type Cache[K comparable, V any] struct {
	capacity int
	data     map[K]V
	order    []K
}

func NewCache[K comparable, V any](capacity int) *Cache[K, V] {
	return &Cache[K, V]{capacity: capacity, data: make(map[K]V)}
}

func (c *Cache[K, V]) Put(k K, v V) {
	if _, exists := c.data[k]; !exists {
		if len(c.order) == c.capacity {
			oldest := c.order[0]
			c.order = c.order[1:]
			delete(c.data, oldest)
		}
		c.order = append(c.order, k)
	}
	c.data[k] = v
}

func (c *Cache[K, V]) Get(k K) (V, bool) {
	v, ok := c.data[k]
	return v, ok
}

func main() {
	cache := NewCache[string, int](2)
	cache.Put("a", 1)
	cache.Put("b", 2)
	cache.Put("c", 3) // "a" chiqib ketadi
	_, okA := cache.Get("a")
	vC, okC := cache.Get("c")
	fmt.Println(okA, vC, okC)
}

