type Cache[K comparable, V any] struct {
	data         map[K]V
	hits, misses int
}

func NewCache[K comparable, V any]() *Cache[K, V] {
	return &Cache[K, V]{data: make(map[K]V)}
}

func (c *Cache[K, V]) GetOrCompute(k K, compute func(K) V) V {
	if v, ok := c.data[k]; ok {
		c.hits++
		return v
	}
	c.misses++
	v := compute(k)
	c.data[k] = v
	return v
}

