func Balanced(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	var st Stack[rune]
	for _, ch := range s {
		switch ch {
		case '(', '[', '{':
			st.Push(ch)
		case ')', ']', '}':
			top, ok := st.Pop()
			if !ok || top != pairs[ch] {
				return false
			}
		}
	}
	return st.Len() == 0
}

