func Eval(expr string) float64 {
	var st Stack[float64]
	for _, tok := range strings.Fields(expr) {
		switch tok {
		case "+", "-", "*", "/":
			b, a := st.Pop(), st.Pop()
			switch tok {
			case "+":
				st.Push(a + b)
			case "-":
				st.Push(a - b)
			case "*":
				st.Push(a * b)
			case "/":
				st.Push(a / b)
			}
		default:
			n, _ := strconv.ParseFloat(tok, 64)
			st.Push(n)
		}
	}
	return st.Pop()
}

func main() {
	fmt.Println(Eval("3 4 + 2 *"))
	fmt.Println(Eval("10 2 8 * + 3 -"))
	fmt.Println(Eval("9 4 /"))
}

