type Graph[T comparable] struct{ adj map[T][]T }

func NewGraph[T comparable]() *Graph[T] {
	return &Graph[T]{adj: make(map[T][]T)}
}

func (g *Graph[T]) AddEdge(a, b T) {
	g.adj[a] = append(g.adj[a], b)
	g.adj[b] = append(g.adj[b], a)
}

func (g *Graph[T]) BFS(start T) []T {
	visited := map[T]bool{start: true}
	queue := []T{start}
	var order []T
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		order = append(order, cur)
		for _, nb := range g.adj[cur] {
			if !visited[nb] {
				visited[nb] = true
				queue = append(queue, nb)
			}
		}
	}
	return order
}

func main() {
	g := NewGraph[string]()
	g.AddEdge("Toshkent", "Samarqand")
	g.AddEdge("Toshkent", "Andijon")
	g.AddEdge("Samarqand", "Buxoro")
	g.AddEdge("Andijon", "Namangan")
	g.AddEdge("Buxoro", "Xiva")
