	return &Counter[K]{counts: make(map[K]int)}
}

func (c *Counter[K]) Add(k K) { c.counts[k]++ }

func (c *Counter[K]) Top(n int) []K {
	keys := make([]K, 0, len(c.counts))
	for k := range c.counts {
		keys = append(keys, k)
	}
	slices.SortFunc(keys, func(a, b K) int {
		return cmp.Or(cmp.Compare(c.counts[b], c.counts[a]), cmp.Compare(a, b))
	})
	return keys[:min(n, len(keys))]
}

func main() {
	c := NewCounter[string]()
	for _, w := range strings.Fields("go tez go sodda tez go oddiy") {
		c.Add(w)
	}
	for _, w := range c.Top(2) {
		fmt.Println(w, c.counts[w])
	}
}

