func Windows[T any](s []T, n int) [][]T {
	if n <= 0 || n > len(s) {
		return nil
	}
	out := make([][]T, 0, len(s)-n+1)
	for i := 0; i+n <= len(s); i++ {
		out = append(out, s[i:i+n])
	}
	return out
}

