	var zero T
	var lastErr error
	for i := 1; i <= attempts; i++ {
		v, err := f()
		if err == nil {
			return v, nil
		}
		lastErr = fmt.Errorf("urinish %d: %w", i, err)
	}
	return zero, lastErr
}

