type job[T any] struct {
	index int
	value T
}

func Pool[T, U any](workers int, in []T, f func(T) U) []U {
	jobs := make(chan job[T])
	out := make([]U, len(in))
	var wg sync.WaitGroup
	for range workers {
		wg.Go(func() {
			for j := range jobs {
				out[j.index] = f(j.value)
			}
		})
	}
	for i, v := range in {
		jobs <- job[T]{i, v}
	}
	close(jobs)
	wg.Wait()
	return out
}

func main() {
	prices := []int{100, 250, 80, 1200}
	withTax := Pool(2, prices, func(p int) int { return p * 112 / 100 }) // 12% soliq
