	if o.ok {
		return o.value
	}
	return def
}

func main() {
	label := Some(42).Map(strconv.Itoa).Map(strings.ToUpper).Map(func(s string) string { return "#" + s })
	fmt.Println(label.OrElse("yo'q"))
	fmt.Println(None[int]().Map(strconv.Itoa).OrElse("yo'q"))
	price := Some(120).Map(func(n int) float64 { return float64(n) * 1.5 })
	fmt.Println(price.OrElse(0))
}

