import (
	"errors"
	"fmt"
	"strconv"
)

type Result[T any] struct {
	val T
	err error
}

func Ok[T any](v T) Result[T]         { return Result[T]{val: v} }
func Fail[T any](err error) Result[T] { return Result[T]{err: err} }

func (r Result[T]) Map[U any](f func(T) U) Result[U] {
	if r.err != nil {
		return Fail[U](r.err)
	}
	return Ok(f(r.val))
}

func (r Result[T]) AndThen[U any](f func(T) Result[U]) Result[U] {
	if r.err != nil {
		return Fail[U](r.err)
	}
	return f(r.val)
}

func (r Result[T]) Unwrap() (T, error) { return r.val, r.err }

func parse(s string) Result[int] {
	n, err := strconv.Atoi(s)
	if err != nil {
		return Fail[int](errors.New("son emas: " + s))
	}
	return Ok(n)
}

func main() {
	double := func(n int) int { return n * 2 }
	fmt.Println(parse("21").Map(double).Unwrap())
	fmt.Println(parse("x1").Map(double).Unwrap())
	fmt.Println(Ok("100").AndThen(parse).Map(double).Unwrap())
}

