import (
	"fmt"
	"iter"
	"slices"
	"strings"
)

type Stream[T any] struct{ seq iter.Seq[T] }

func From[T any](items ...T) Stream[T] {
	return Stream[T]{slices.Values(items)}
}

func (s Stream[T]) Filter(pred func(T) bool) Stream[T] {
	return Stream[T]{func(yield func(T) bool) {
		for v := range s.seq {
			if pred(v) && !yield(v) {
				return
			}
		}
	}}
}

func (s Stream[T]) Map[U any](f func(T) U) Stream[U] {
	return Stream[U]{func(yield func(U) bool) {
		for v := range s.seq {
			if !yield(f(v)) {
				return
			}
		}
	}}
}

func (s Stream[T]) Collect() []T { return slices.Collect(s.seq) }

func main() {
	res := From(3, 8, 1, 12, 5, 20).
		Filter(func(n int) bool { return n > 4 }).
		Map(func(n int) string { return fmt.Sprintf("#%d", n) }).
		Map(strings.ToUpper).
		Collect()
	fmt.Println(res)
}

