import "fmt"

type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

func (s *Stack[T]) IndexOf[K comparable](key func(T) K, want K) int {
	for i, it := range s.items {
		if key(it) == want {
			return i
		}
	}
	return -1
}

type User struct {
	ID   int
	Name string
}

func main() {
	var users Stack[User]
	users.Push(User{1, "Aziz"})
	users.Push(User{2, "Dilnoza"})
	users.Push(User{3, "Bobur"})

	fmt.Println(users.IndexOf(func(u User) int { return u.ID }, 3))
	fmt.Println(users.IndexOf(func(u User) string { return u.Name }, "Dilnoza"))
	fmt.Println(users.IndexOf(func(u User) string { return u.Name }, "Malika"))
}

