type Table[T any] struct{ rows []T }

func From[T any](rows ...T) Table[T] { return Table[T]{rows} }

func (t Table[T]) Where(pred func(T) bool) Table[T] {
	var out []T
	for _, r := range t.rows {
		if pred(r) {
			out = append(out, r)
		}
	}
	return Table[T]{out}
}

func (t Table[T]) OrderBy[K cmp.Ordered](key func(T) K) Table[T] {
	out := slices.Clone(t.rows)
	slices.SortFunc(out, func(a, b T) int { return cmp.Compare(key(a), key(b)) })
	return Table[T]{out}
}

func (t Table[T]) Select[U any](f func(T) U) Table[U] {
	out := make([]U, 0, len(t.rows))
	for _, r := range t.rows {
		out = append(out, f(r))
	}
	return Table[U]{out}
}

type Order struct {
	Customer string
	Total    int
}

func main() {
	orders := From(
		Order{"Aziz", 120}, Order{"Dilnoza", 450}, Order{"Bobur", 80}, Order{"Malika", 300},
	)
	names := orders.
		Where(func(o Order) bool { return o.Total >= 100 }).
		OrderBy(func(o Order) int { return -o.Total }).
		Select(func(o Order) string { return fmt.Sprintf("%s (%d)", o.Customer, o.Total) })
	fmt.Println(names.rows)
}

