import "fmt"

type Node[N Node[N]] interface {
	comparable
	Neighbors() []N
}

type Room string

var doors = map[Room][]Room{
	"kirish":  {"zal", "oshxona"},
	"zal":     {"balkon"},
	"oshxona": {"balkon"},
	"balkon":  nil,
}

func (r Room) Neighbors() []Room { return doors[r] }

func Reachable[N Node[N]](start N) []N {
	seen := map[N]bool{start: true}
	queue := []N{start}
	var order []N
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		order = append(order, cur)
		for _, nb := range cur.Neighbors() {
			if !seen[nb] {
				seen[nb] = true
				queue = append(queue, nb)
			}
		}
	}
	return order
}

func main() {
	fmt.Println(Reachable(Room("kirish")))
}

