import "fmt"

func Get[T any](m map[string]any, key string) (T, error) {
	var zero T
	raw, ok := m[key]
	if !ok {
		return zero, fmt.Errorf("%q kaliti yo'q", key)
	}
	v, ok := raw.(T)
	if !ok {
		return zero, fmt.Errorf("%q: %T kutilgan, %T berilgan", key, zero, raw)
	}
	return v, nil
}

func main() {
	cfg := map[string]any{"port": 8080, "host": "localhost", "debug": true}
	port, _ := Get[int](cfg, "port")
	host, _ := Get[string](cfg, "host")
	fmt.Println(host, port+1)
	_, err := Get[string](cfg, "port")
	fmt.Println(err)
	_, err = Get[bool](cfg, "verbose")
	fmt.Println(err)
}
